def _sha(path):
    h = hashlib.sha256()
    with Path(path).open('rb') as stream:
        for chunk in iter(lambda:stream.read(1<<20),b''):h.update(chunk)
    return h.hexdigest()


def source_closure():
    """Validate every original member, including nonexecuted transport metadata."""
    raw=base64.b64decode(_SOURCE_ARCHIVE_B64)
    if hashlib.sha256(raw).hexdigest()!=SOURCE_ARCHIVE_SHA256:
        raise ArtifactUnavailable('Embedded released-source archive changed')
    source={}
    with tarfile.open(fileobj=io.BytesIO(raw),mode='r:gz') as archive:
        for member in archive.getmembers():
            if not member.isfile() or member.name not in SOURCE_HASHES:
                raise ArtifactUnavailable('Unexpected released source member')
            value=archive.extractfile(member).read()
            if hashlib.sha256(value).hexdigest()!=SOURCE_HASHES[member.name]:
                raise ArtifactUnavailable('Released source bytes changed: '+member.name)
            source[member.name]=value
    if set(source)!=set(SOURCE_HASHES):raise ArtifactUnavailable('Released source closure incomplete')
    return source


class _EmbeddedLoader(importlib.abc.Loader):
    def __init__(self,family,relative,source):
        self.family,self.relative,self.source=family,relative,source
    def create_module(self,spec):return None
    def exec_module(self,module):
        text=self.source.decode('utf-8')
        filename='astra300_embedded/'+self.relative+'@'+SOURCE_HASHES[self.relative]
        module.__file__=filename
        linecache.cache[filename]=(len(text),None,text.splitlines(True),filename)
        original_import=builtins.__import__
        prefix='_astra300_released_'+self.family
        def family_import(name,globals=None,locals=None,fromlist=(),level=0):
            if level==0 and name.split('.')[0] in ('models','utils'):
                translated=prefix+'.'+name
                original_import(translated,globals,locals,fromlist or ('*',),0)
                return sys.modules[translated] if fromlist else sys.modules[prefix+'.'+name.split('.')[0]]
            return original_import(name,globals,locals,fromlist,level)
        module.__dict__['__builtins__']=dict(vars(builtins),__import__=family_import)
        exec(compile(text,filename,'exec'),module.__dict__)
    def get_source(self,fullname):return self.source.decode('utf-8')


class _EmbeddedFinder(importlib.abc.MetaPathFinder):
    def __init__(self,source):self.source=source
    def find_spec(self,fullname,path=None,target=None):
        for family in ('foris','insid3'):
            prefix='_astra300_released_'+family
            if fullname==prefix:
                return importlib.util.spec_from_loader(fullname,_RootLoader(),is_package=True)
            if not fullname.startswith(prefix+'.'):continue
            suffix=fullname[len(prefix)+1:].replace('.','/')
            package=family+'/'+suffix+'/__init__.py';normal=family+'/'+suffix+'.py'
            relative=package if package in self.source else normal
            if relative in self.source:
                return importlib.util.spec_from_loader(fullname,_EmbeddedLoader(family,relative,self.source[relative]),is_package=relative==package)
        return None


class _RootLoader(importlib.abc.Loader):
    def create_module(self,spec):return None
    def exec_module(self,module):module.__path__=[]


def _family(name):
    with _LOCK:
        if name not in _FAMILIES:
            prefix='_astra300_released_'+name
            if not any(isinstance(item,_EmbeddedFinder) for item in sys.meta_path):
                sys.meta_path.insert(0,_EmbeddedFinder(source_closure()))
            try:
                model=importlib.import_module(prefix+'.models.'+name)
                data=importlib.import_module(prefix+'.utils.data')
                refinement=importlib.import_module(prefix+'.utils.refinement')
            except (ImportError,RuntimeError,OSError) as error:
                # Failed import cannot leave a half-initialized family registered.
                for key in list(sys.modules):
                    if key==prefix or key.startswith(prefix+'.'):sys.modules.pop(key,None)
                raise ArtifactUnavailable('Released '+name+' CPU dependency unavailable: '+repr(error)) from error
            _FAMILIES[name]=(model,data,refinement)
        return _FAMILIES[name]


def _assets(ep):
    value=artifact(ep,'complete_baseline_assets')
    if not isinstance(value,dict) or value.get('schema')!='ASTRA_COMPLETE_BASELINE_ASSETS_V1':
        raise ArtifactUnavailable('Explicit complete-baseline assets binding required')
    if value.get('source_archive_sha256')!=SOURCE_ARCHIVE_SHA256:
        raise ArtifactUnavailable('Complete-baseline source binding differs from embedded release')
    expected=ep.producer.get('model_assets',ep.producer)
    checkpoint=expected.get('checkpoint_sha256')
    config=expected.get('config_sha256',expected.get('model_config_sha256'))
    if value.get('checkpoint_sha256')!=checkpoint or value.get('config_sha256')!=config:
        raise ArtifactUnavailable('Native basis/cache and host must share checkpoint/config identity')
    return value


def _basis(ep,assets):
    spec=assets.get('positional_basis',{})
    if spec.get('source_input')!='normalized_black_image' or spec.get('state')!='NATIVE_BASIS_FROZEN':
        raise ArtifactUnavailable('Actual normalized-black native U500 binding required')
    path=Path(spec.get('path',''))
    if not spec.get('sha256') or not path.is_file() or _sha(path)!=spec['sha256']:
        raise ArtifactUnavailable('Missing/changed source-native basis asset: '+str(path))
    key=(str(path.resolve()),spec['sha256'])
    if key not in _ASSET_CACHE:
        if path.suffix=='.npz':
            if 'key' not in spec:raise ArtifactUnavailable('NPZ native basis requires an exact array key')
            with np.load(path,allow_pickle=False) as pack:matrix=pack[spec['key']].copy()
            if matrix.dtype!=np.float32:raise ArtifactUnavailable('Native basis FP32 values must be retained')
            value=torch.from_numpy(matrix)
        elif path.suffix in ('.pt','.pth'):
            document=torch.load(path,map_location='cpu',weights_only=True)
            if (not isinstance(document,dict) or document.get('state')!='NATIVE_BASIS_FROZEN'
                    or document.get('source_input')!='normalized_black_image'):
                raise ArtifactUnavailable('Native basis PT provenance differs from binding')
            value=document['basis']
            if value.dtype!=torch.float32:raise ArtifactUnavailable('Native basis FP32 values must be retained')
        else:raise ArtifactUnavailable('Only bound NPZ/PT native basis assets are supported')
        if tuple(value.shape)!=(1024,500) or not torch.isfinite(value).all():
            raise ArtifactUnavailable('Exact released dimension1024/rank500 native basis required')
        eigen=torch.linalg.eigvalsh(value.double().T@value.double())
        defect=float((eigen-1).abs().max())
        if defect>=.01:raise ArtifactUnavailable('Original native basis is not near-unit/well-conditioned')
        digest=array_hash(value.numpy())
        if spec.get('array_sha256') and spec['array_sha256']!=digest:
            raise ArtifactUnavailable('Native basis array identity differs')
        _ASSET_CACHE[key]=(value.detach().clone(),dict(path=str(path),sha256=spec['sha256'],
            array_sha256=digest,source_input=spec['source_input'],rank=500,dimension=1024,
            native_numerical_gram_spectral_defect=defect,matrix_preserved_without_QR_or_column_rescaling=True))
    return _ASSET_CACHE[key]


def _validate_rgb_geometry(ep):
    if ep.r_rgb is None or ep.q_rgb is None or ep.reference_mask is None:
        raise ArtifactUnavailable('Complete released baselines require original hash-bound R/Q RGB and MR')
    if ep.reference_mask.dtype!=bool or ep.reference_mask.shape!=ep.r_rgb.shape[:2] or ep.q_rgb.shape[:2]!=tuple(ep.original_shape):
        raise ArtifactUnavailable('Complete original RGB/MR geometry required')
    for name in ('reference_geometry','query_geometry'):
        geometry=getattr(ep,name)
        if (not geometry or geometry.get('view_side')!=1024 or list(geometry.get('resized_hw',()))!=[1024,1024]
                or list(geometry.get('padding_top_left',()))!=[0,0]):
            raise ArtifactUnavailable('Released stretch-to1024 transform does not match native cache '+name)
    if ep.r_hw!=(64,64) or ep.q_hw!=(64,64) or ep.q.shape[1]!=1024:
        raise ArtifactUnavailable('Actual DINOv3-L native1024 grid required for complete baselines')
    if ep.producer.get('kind')!='frozen_DINOv3_FP32_native_final_LN_patches' or ep.producer.get('FoRIS_Part1_applied') is not False:
        raise ArtifactUnavailable('Complete baseline injection requires actual pre-unit FP32 native cache')


def _native_cache(ep):
    """Read the exact already-encoded pack; never normalize/recreate its features."""
    _validate_rgb_geometry(ep)
    row=getattr(getattr(ep,'provider',None),'row',None)
    if row is None:
        row=artifact(ep,'native_feature_pack_binding')
    if not isinstance(row,dict) or not row.get('sha256') or _sha(row['feature_pack'])!=row['sha256']:
        raise ArtifactUnavailable('Actual native feature-pack hash binding required')
    with np.load(row['feature_pack'],allow_pickle=False) as pack:
        required={'q','r','foreground_weight','valid_weight','query_geometry_json','producer_json'}
        if set(pack.files)!=required:raise ArtifactUnavailable('Input pack is not inference-only native format')
        producer=json.loads(pack['producer_json'].item())
        if producer!=ep.producer:raise ArtifactUnavailable('Native feature producer differs from loaded Episode')
        raw={name:pack[name].copy() for name in ('r','q')}
        if any(a.dtype!=np.float32 or a.shape!=(4096,1024) or not np.isfinite(a).all() for a in raw.values()):
            raise ArtifactUnavailable('Bound actual FP32 raw final-LN[4096,1024] required')
        if not np.array_equal(pack['foreground_weight'],ep.wf) or not np.array_equal(pack['valid_weight'],ep.wvalid):
            raise ArtifactUnavailable('Cache reference weights/unknown domain differ from complete Episode')
        cache_geometry=json.loads(pack['query_geometry_json'].item())
        if cache_geometry!=ep.query_geometry:raise ArtifactUnavailable('Native query physical geometry differs')
    for name in ('q','r'):
        if not np.allclose(unit(raw[name]),getattr(ep,name),atol=1e-6,rtol=1e-6):
            raise ArtifactUnavailable('Actual raw cache is not the Episode unit descriptor source')
    image_hashes=ep.producer.get('source_image_hashes')
    if not isinstance(image_hashes,list) or len(image_hashes)!=2:
        raise ArtifactUnavailable('Explicit ordered source R/Q file hashes required')
    for name,expected in (('r_rgb',image_hashes[0]),('q_rgb',image_hashes[1]),('reference_mask',ep.producer.get('reference_mask_sha256'))):
        if not expected or row.get(name+'_sha256')!=expected or _sha(row[name])!=expected:
            raise ArtifactUnavailable('Original source byte binding differs for '+name)
    # Decoded immutable Episode RGB/MR must still equal their bound files.
    for name in ('q_rgb','r_rgb'):
        with Image.open(row[name]) as image:decoded=np.asarray(image.convert('RGB'))
        if not np.array_equal(decoded,getattr(ep,name)):raise ArtifactUnavailable('Episode RGB was changed after native binding')
    with Image.open(row['reference_mask']) as image:mask=np.asarray(image)!=0
    if not np.array_equal(mask,ep.reference_mask):raise ArtifactUnavailable('Complete original MR changed')
    resized=np.asarray(Image.fromarray(ep.reference_mask.astype(np.uint8)).resize((1024,1024),Image.Resampling.NEAREST),float)
    coverage=resized.reshape(64,16,64,16).mean((1,3)).ravel()
    if not np.array_equal(coverage,ep.wf) or not np.array_equal(ep.wvalid,np.ones(4096)):
        raise ArtifactUnavailable('Released MR transform does not match native area weights')
    return raw,dict(feature_pack=str(row['feature_pack']),sha256=row['sha256'],producer=producer,
                    source_image_hashes=image_hashes,reference_mask_sha256=ep.producer['reference_mask_sha256'],
                    raw_array_hashes={name:array_hash(value) for name,value in raw.items()},
                    raw_dtype='float32',raw_stage='native final-LN before unit/Part1',
                    decoded_original_files_and_mask_weights_verified=True)


class CacheNativeFeatures(torch.nn.Module):
    """Actual bound cache feature reader; accepts only the original source tensors."""
    def __init__(self,ep,data_module,raw):
        super().__init__();self.ep=ep;self.calls=0;self.expected={};self.maps={};self.receipt=[]
        transform=data_module.build_transform(1024)
        for role in ('r','q'):
            image=Image.fromarray(np.asarray(getattr(ep,role+'_rgb'),np.uint8),'RGB')
            actual=transform(image).float()
            canvas=np.asarray(image.resize((1024,1024),Image.Resampling.BILINEAR)).copy()
            tensor=torch.from_numpy(canvas).permute(2,0,1).float()/255
            mean=tensor.new_tensor((.485,.456,.406))[:,None,None]
            std=tensor.new_tensor((.229,.224,.225))[:,None,None]
            expected=(tensor-mean)/std
            if not torch.equal(actual,expected):
                raise ArtifactUnavailable('Original released transform is not byte/numerically identical to native cache '+role)
            self.expected[role]=actual.detach().clone()
            self.maps[role]=torch.from_numpy(raw[role].reshape(64,64,1024).transpose(2,0,1).copy())[None]
        native_mask=torch.from_numpy(ep.reference_mask.copy()).float()[None,None]
        self.mask1024=torch.nn.functional.interpolate(native_mask,size=(1024,1024),mode='nearest')[0,0].bool()

    def verify_host_inputs(self,host):
        if (host._ref_images is None or host._ref_images.shape!=(1,3,1024,1024)
                or not torch.equal(host._ref_images[0],self.expected['r'])):
            raise ArtifactUnavailable('set_reference source transform differs from actual native cache')
        target=host._tgt_image.reshape(-1,3,1024,1024)
        if target.shape!=(1,3,1024,1024) or not torch.equal(target[0],self.expected['q']):
            raise ArtifactUnavailable('set_target source transform differs from actual native cache')
        if host._ref_masks.shape!=(1,1024,1024) or not torch.equal(host._ref_masks[0],self.mask1024):
            raise ArtifactUnavailable('set_reference original MR transform differs from cache label source')
        self.receipt.append(dict(source_reference_tensor_array_sha256=array_hash(host._ref_images[0].numpy()),
                                 source_target_tensor_array_sha256=array_hash(target[0].numpy()),
                                 source_reference_mask1024_array_sha256=array_hash(self.mask1024.numpy()),
                                 cache_reference_coverage_array_sha256=array_hash(self.ep.wf),
                                 reference_mask_preprocessing='released Torch nearest; native pack coverage separately checked against its original PIL nearest'))

    def get_intermediate_layers(self,x,n=1,reshape=True):
        if n!=1 or not reshape or x.dtype!=torch.float32 or x.device.type!='cpu' or tuple(x.shape)!=(2,3,1024,1024):
            raise ArtifactUnavailable('Cache reader only supports actual released paired FP32 CPU R/Q extraction')
        if not torch.equal(x[0],self.expected['r']) or not torch.equal(x[1],self.expected['q']):
            raise ArtifactUnavailable('Requested feature input does not equal the bound original R/Q transform')
        self.calls+=1
        self.receipt.append(dict(batch=2,source_order=['r','q'],actual_new_encoder_forwards=0,
                                 exact_normalized_input_tensor_match=True,native_dtype='float32'))
        return (torch.cat((self.maps['r'],self.maps['q']),dim=0).clone(),)


@contextmanager
def _original_basis(host_class,basis):
    original=host_class._build_positional_basis
    def cached(this,device):
        if this.image_size!=1024 or this.svd_components!=500 or str(device)!='cpu':
            raise ArtifactUnavailable('Released native positional-basis configuration changed')
        return basis.clone()
    with _LOCK:
        host_class._build_positional_basis=cached
        try:yield
        finally:host_class._build_positional_basis=original


def _host(ep,family,refiner,raw,basis):
    model,data,refinement=_family(family)
    encoder=CacheNativeFeatures(ep,data,raw)
    host_class=model.FoRIS if family=='foris' else model.INSID3
    kwargs=dict(encoder=encoder,image_size=1024,svd_components=500,tau=.6,
                mask_refiner=refiner,resize_to_orig_size=True,device='cpu')
    if family=='insid3':kwargs.update(merge_threshold=.2,crf_size=640)
    try:
        with _original_basis(host_class,basis):host=host_class(**kwargs).eval().requires_grad_(False)
    except (ImportError,RuntimeError,OSError) as error:
        raise ArtifactUnavailable('Complete '+family+' '+refiner+' CPU construction unavailable: '+repr(error)) from error
    return host,encoder,refinement,kwargs


def _run_host(ep,host,encoder):
    host.set_reference(Image.fromarray(np.asarray(ep.r_rgb,np.uint8),'RGB'),torch.from_numpy(ep.reference_mask.copy()))
    host.set_target(Image.fromarray(np.asarray(ep.q_rgb,np.uint8),'RGB'))
    encoder.verify_host_inputs(host)
    return host.segment()


def _dependencies():
    import importlib.metadata
    versions={}
    for name in ('torch','torchvision','einops','scikit-learn','pycocotools'):
        try:versions[name]=importlib.metadata.version(name)
        except importlib.metadata.PackageNotFoundError:versions[name]='unavailable'
    crf=sys.modules.get('CRF')
    if crf is not None:
        path=getattr(crf,'__file__',None)
        versions['CRF']=dict(path=path,sha256=_sha(path) if path and Path(path).is_file() else None)
    return versions


def _episode_bundle(ep):
    global _LAST_EPISODE,_LAST_OUTPUTS
    if ep.producer.get('synthetic_contract_fixture') or ep.producer.get('synthetic'):
        raise ArtifactUnavailable('Complete released baseline controls refuse synthetic feature producers')
    _validate_rgb_geometry(ep)
    key=(id(ep),ep.source_id,array_hash(ep.reference_mask),array_hash(ep.wf))
    with _LOCK:
        if key!=_LAST_EPISODE:
            raw,binding=_native_cache(ep);assets=_assets(ep);basis,basis_binding=_basis(ep,assets)
            _LAST_EPISODE=key;_LAST_OUTPUTS={'raw':raw,'raw_binding':binding,'basis':basis,'basis_binding':basis_binding}
        return _LAST_OUTPUTS


def _info(bundle,family,refiner,seconds,calls,config):
    clean_config={key:value for key,value in config.items() if key!='encoder'}
    return dict(control=True,method='complete released '+family,refiner=refiner,
                host_config=clean_config,source_archive_sha256=SOURCE_ARCHIVE_SHA256,
                third_party_source_hashes={key:value for key,value in SOURCE_HASHES.items() if key.startswith(family+'/')},
                actual_native_cache=bundle['raw_binding'],positional_basis=bundle['basis_binding'],
                dependencies=_dependencies(),device='cpu',cache_native_feature_reads=calls,
                actual_new_encoder_forwards=0,query_GT_read=False,wall_seconds=seconds,
                precision='source CPU branch FP32; original clustering/vote/Part1/CRF retained',
                published_hub_numerical_equivalence='unverified',quality='unknown')


def complete_foris(ep):
    bundle=_episode_bundle(ep)
    with _LOCK:
        if 'foris_result' not in bundle:
            wall=time.monotonic();host,encoder,_,config=_host(ep,'foris','crf',bundle['raw'],bundle['basis'])
            captured={};original=host._binarize_response
            def capture(score_hw,*,target_hw):
                score=score_hw-score_hw.min();score=score/score.max().clamp_min(1e-6)
                captured['p0']=readonly(score.detach().cpu().numpy())
                return original(score_hw,target_hw=target_hw)
            host._binarize_response=capture
            try:
                with torch.inference_mode(),torch.autocast('cpu',enabled=False):mask=_run_host(ep,host,encoder)
            except (RuntimeError,ImportError,OSError) as error:
                raise ArtifactUnavailable('Complete FoRIS including original CPU CRF failed: '+repr(error)) from error
            finally:
                host._binarize_response=original
                host._ref_images=host._ref_masks=host._tgt_image=host._orig_tgt_size=None
            if 'p0' not in captured or mask.dtype!=torch.bool or tuple(mask.shape)!=tuple(ep.original_shape):
                raise ArtifactUnavailable('Complete original-resolution FoRIS/Part4 output missing')
            info=_info(bundle,'foris','crf',time.monotonic()-wall,encoder.calls,config)
            producer=dict(kind='complete_released_FoRIS_Part1_Part2_Part3_Part4_CRF',
                          source_image_hashes=bundle['raw_binding']['producer']['source_image_hashes'],
                          raw_feature_producer=bundle['raw_binding']['producer'],FoRIS_Part1_applied='original_conditional_rule',
                          source_archive_sha256=SOURCE_ARCHIVE_SHA256,positional_basis_sha256=bundle['basis_binding']['sha256'],
                          final_field='actual Part4 response source minmax before source bilinear/binarize',host_config=info['host_config'])
            renderer=dict(kind='released_FoRIS_source_finalize',native_field_hw=[64,64],threshold=.5,
                          source_bilinear_to_1024_then_threshold=True,CRF='source DenseGaussianCRF1024',
                          final_original_resize='source bilinear of complete binary mask then strict>.5',
                          original_shape=list(ep.original_shape),zero_module='actual complete original FoRIS mask')
            bundle.update(foris_p0=captured['p0'],foris_mask0=readonly(mask.cpu().numpy()),
                          foris_producer=producer,foris_renderer=renderer,
                          foris_result=Result(mask_original=readonly(mask.cpu().numpy()),info=info))
        return bundle['foris_result']


def _insid3_core(ep):
    bundle=_episode_bundle(ep)
    if 'insid3_bilinear_result' not in bundle:
        wall=time.monotonic();host,encoder,_,config=_host(ep,'insid3','bilinear',bundle['raw'],bundle['basis'])
        captured={};original=host._finalize_mask
        def capture(mask,target):
            captured['native_mask']=mask.detach().clone();captured['target']=target.detach().clone()
            return original(mask,target)
        host._finalize_mask=capture
        try:
            with torch.inference_mode(),torch.autocast('cpu',enabled=False):mask=_run_host(ep,host,encoder)
        except (RuntimeError,ImportError,OSError) as error:
            raise ArtifactUnavailable('Complete released INSID3 CPU core failed: '+repr(error)) from error
        finally:host._finalize_mask=original;host.reset_state()
        if not captured or mask.dtype!=torch.bool or tuple(mask.shape)!=tuple(ep.original_shape):
            raise ArtifactUnavailable('Complete released INSID3 core output missing')
        info=_info(bundle,'insid3','bilinear',time.monotonic()-wall,encoder.calls,config)
        bundle.update(insid3_native_mask=captured['native_mask'],insid3_target=captured['target'],
                      insid3_core_wall_seconds=info['wall_seconds'],
                      insid3_bilinear_result=Result(mask_original=readonly(mask.cpu().numpy()),info=info))
    return bundle


def complete_insid3_bilinear(ep):
    with _LOCK:return _insid3_core(ep)['insid3_bilinear_result']


def complete_insid3_crf640(ep):
    with _LOCK:
        bundle=_insid3_core(ep)
        if 'insid3_crf_result' not in bundle:
            wall=time.monotonic();host,encoder,_,config=_host(ep,'insid3','crf',bundle['raw'],bundle['basis'])
            host._orig_tgt_size=tuple(ep.original_shape)
            try:
                with torch.inference_mode(),torch.autocast('cpu',enabled=False):
                    mask=host._finalize_mask(bundle['insid3_native_mask'].clone(),bundle['insid3_target'].clone())
            except (RuntimeError,ImportError,OSError) as error:
                raise ArtifactUnavailable('Original released INSID3 CPU640 CRF unavailable: '+repr(error)) from error
            finally:host.reset_state()
            info=_info(bundle,'insid3','crf640',time.monotonic()-wall,0,config)
            info.update(core_reused_exactly_from_complete_bilinear_pipeline=True,
                        shared_core_wall_seconds=bundle['insid3_core_wall_seconds'],
                        full_cached_pipeline_wall_seconds=bundle['insid3_core_wall_seconds']+info['wall_seconds'])
            if mask.dtype!=torch.bool or tuple(mask.shape)!=tuple(ep.original_shape):
                raise ArtifactUnavailable('Complete original-size INSID3 CRF output required')
            bundle['insid3_crf_result']=Result(mask_original=readonly(mask.cpu().numpy()),info=info)
        return bundle['insid3_crf_result']


def require(ep,name):
    if name not in ('foris_p0','foris_mask0','foris_producer','foris_renderer','foris_host'):
        raise ArtifactUnavailable('Unknown complete FoRIS host resource: '+name)
    complete_foris(ep)
    bundle=_episode_bundle(ep)
    return bundle['foris_result'] if name=='foris_host' else bundle[name]


def foris_p0(ep):return require(ep,'foris_p0')
def foris_mask0(ep):return require(ep,'foris_mask0')
def foris_producer(ep):return require(ep,'foris_producer')
def foris_renderer(ep):return require(ep,'foris_renderer')


def bind_assets(ep,assets):
    """Root attaches one immutable, shared asset descriptor to each worker episode."""
    from .common import as_episode
    return as_episode(ep,artifacts=dict(getattr(ep,'artifacts',{}),complete_baseline_assets=assets),
                      provider=getattr(ep,'provider',None))


